```ts
function validateProduct(input: unknown): { value?: ProductRecord; errors: FieldError[] } {
  const errors: FieldError[] = [];
  if (typeof input !== 'object' || input === null || Array.isArray(input)) {
    return { errors: [{ scope:'product', field:'body', message:'请求内容必须是商品对象' }] };
  }
  const obj = input as Record<string, unknown>;
  const name = typeof obj.name === 'string' ? obj.name.trim() : '';
  if (!name) errors.push({ scope:'product', field:'name', message:'商品名称不能为空' });

  if (!Array.isArray(obj.specs) || obj.specs.length === 0) {
    errors.push({ scope:'product', field:'specs', message:'商品至少需要一条规格' });
    return { errors };
  }

  const seenSpecs = new Set<string>();
  const specs: SpecRecord[] = [];
  obj.specs.forEach((rawSpec, i) => {
    const specNum = i + 1;
    if (typeof rawSpec !== 'object' || rawSpec === null || Array.isArray(rawSpec)) {
      errors.push({ scope:'spec', spec: specNum, field:'spec', message:'规格格式不正确' });
      return;
    }
    const s = rawSpec as Record<string, unknown>;
    // attributes
    const attrs: {name:string; value:string}[] = [];
    if (!Array.isArray(s.attributes) || s.attributes.length === 0) {
      errors.push({ scope:'spec', spec: specNum, field:'attributes', message:'每条规格至少需要一个属性' });
    } else {
      const seenNames = new Set<string>();
      s.attributes.forEach((rawAttr, j) => {
        const attrNum = j + 1;
        if (typeof rawAttr !== 'object' || rawAttr === null || Array.isArray(rawAttr)) {
          errors.push({ scope:'spec', spec: specNum, field:'attribute', attribute: attrNum, message:'属性格式不正确' });
          return;
        }
        const a = rawAttr as Record<string, unknown>;
        const an = typeof a.name === 'string' ? a.name.trim() : '';
        const av = typeof a.value === 'string' ? a.value.trim() : '';
        if (!an) errors.push({ scope:'spec', spec: specNum, field:'attribute', attribute: attrNum, subfield:'name', message:`第${specNum}条规格第${attrNum}个属性的名称不能为空` });
        if (!av) errors.push({ scope:'spec', spec: specNum, field:'attribute', attribute: attrNum, subfield:'value', message:`第${specNum}条规格第${attrNum}个属性的值不能为空` });
        if (an) {
          if (seenNames.has(an)) errors.push({ scope:'spec', spec: specNum, field:'attributes', message:`第${specNum}条规格内属性名称「${an}」重复` });
          else seenNames.add(an);
        }
        attrs.push({ name: an, value: av });
      });
    }
    // price
    let price: string | undefined;
    if (typeof s.price !== 'string' || !PRICE_RE.test(s.price)) {
      errors.push({ scope:'spec', spec: specNum, field:'price', message:`第${specNum}条规格的售价必须为十进制金额字符串（最多两位小数，不为负数）` });
    } else {
      price = normalizePrice(s.price);
    }
    // stock
    let stock: number | undefined;
    if (typeof s.stock !== 'number' || !Number.isSafeInteger(s.stock) || s.stock < 0) {
