function validateForm(){
  const errs = [];
  if(!formState.name.trim()) errs.push({scope:'product', field:'name', message:'商品名称不能为空'});
  if(formState.specs.length === 0) errs.push({scope:'product', field:'specs', message:'商品至少需要一条规格'});
  const specKeys = [];
  formState.specs.forEach((s, i) => {
    const n = i+1;
    const attrs = s.attributes.map(a => ({name:a.name.trim(), value:a.value.trim()}));
    if(attrs.length === 0) errs.push({scope:'spec', spec:n, field:'attributes', message:`第${n}条规格至少需要一个属性`});
    const names = new Set();
    attrs.forEach((a, j) => {
      const an = j+1;
      if(!a.name) errs.push({scope:'spec', spec:n, field:'attribute', attribute:an, subfield:'name', message:`第${n}条规格第${an}个属性名称不能为空`});
      if(!a.value) errs.push({scope:'spec', spec:n, field:'attribute', attribute:an, subfield:'value', message:`第${n}条规格第${an}个属性值不能为空`});
      if(a.name){ if(names.has(a.name)) errs.push({scope:'spec', spec:n, field:'attributes', message:`第${n}条规格内属性名称重复`}); else names.add(a.name); }
    });
    if(!PRICE_RE.test(s.price.trim())) errs.push({scope:'spec', spec:n, field:'price', message:`第${n}条规格售价格式不正确（须为十进制金额，最多两位小数，不为负数）`});
    const stockNum = s.stock.trim()==='' ? NaN : Number(s.stock.trim());
    if(!Number.isSafeInteger(stockNum) || stockNum < 0) errs.push({scope:'spec', spec:n, field:'stock', message:`第${n}条规格库存必须为非负整数`});
    if(attrs.length && attrs.every(a=>a.name&&a.value)){
      const key = attrs.map(a=>a.name+'='+a.value).sort().join('&');
      if(specKeys.includes(key)) errs.push({scope:'spec', spec:n, field:'duplicate', message:`第${n}条规格与前面的规格重复`});
      else specKeys.push(key);
    }
  });
  return errs;
}
