var PRICE_RE = /^(0|[1-9]\d*)(\.\d{1,2})?$/;

function validateForm(){
  var errs = [];
  if(!formState.name.trim()) errs.push({scope:'product', field:'name', message:'商品名称不能为空'});
  if(!formState.specs.length) errs.push({scope:'product', field:'specs', message:'商品至少需要一条规格'});
  var specKeys = [];
  formState.specs.forEach(function(s, i){
    var n = i + 1;
    var attrs = s.attributes.map(function(a){ return {name:a.name.trim(), value:a.value.trim()}; });
    if(!attrs.length) errs.push({scope:'spec', spec:n, field:'attributes', message:'第'+n+'条规格至少需要一个属性'});
    var names = {};
    attrs.forEach(function(a, j){
      var an = j + 1;
      if(!a.name) errs.push({scope:'spec', spec:n, field:'attribute', attribute:an, subfield:'name', message:'第'+n+'条规格第'+an+'个属性的名称不能为空'});
      if(!a.value) errs.push({scope:'spec', spec:n, field:'attribute', attribute:an, subfield:'value', message:'第'+n+'条规格第'+an+'个属性的值不能为空'});
      if(a.name){
        if(names[a.name]) errs.push({scope:'spec', spec:n, field:'attributes', message:'第'+n+'条规格内属性名称「'+a.name+'」重复'});
        else names[a.name] = true;
      }
    });
    if(!PRICE_RE.test(s.price.trim())) errs.push({scope:'spec', spec:n, field:'price', message:'第'+n+'条规格售价格式不正确：须为十进制金额字符串，允许零和最多两位小数，不接受负数、指数或千位分隔符'});
    var stockRaw = s.stock.trim();
    var stockNum = stockRaw === '' ? NaN : Number(stockRaw);
    if(!Number.isSafeInteger(stockNum) || stockNum < 0) errs.push({scope:'spec', spec:n, field:'stock', message:'第'+n+'条规格库存必须为非负整数，不能是小数或空值'});
    if(attrs.length && attrs.every(function(a){ return a.name && a.value; })){
      var key = attrs.map(function(a){ return a.name + '=' + a.value; }).sort().join('&');
      if(specKeys.indexOf(key) !== -1) errs.push({scope:'spec', spec:n, field:'duplicate', message:'第'+n+'条规格与前面的规格重复（属性名称和值完全相同，与填写顺序无关）'});
      else specKeys.push(key);
    }
  });
  return errs;
}
